"""Compile dated sequence-I strategy facts for the native opening chooser."""

import argparse
import json
from pathlib import Path


def main():
    parser = argparse.ArgumentParser()
    parser.add_argument("source", type=Path)
    parser.add_argument("output", type=Path)
    args = parser.parse_args()
    rows = json.loads(args.source.read_text(encoding="utf-8-sig"))["strategies"]
    seen = set()
    lines = [
        "#pragma once", "", "#include <array>", "#include <string_view>", "",
        "// Sequence I, 2026-11-10 PRTS/SquadPool snapshot; CC BY-NC-SA 3.0.",
        "// Generated by tools/SPA/generate_strategy_catalogue.py; facts are not win estimates.",
        "namespace asst::spa", "{", "struct StrategyCatalogueEntry", "{",
        "    std::string_view id;", "    std::string_view name;", "    std::string_view leader;",
        "    int initial_life;", "    std::string_view pact;", "    std::string_view effect;",
        "    bool passive;", "    bool click;", "    bool drag;", "};", "",
        f"inline constexpr std::array<StrategyCatalogueEntry, {len(rows)}> StrategyCatalogue {{{{",
    ]
    for row in rows:
        if (not row["band_id"] or row["band_id"] in seen or not row["effect"]
                or not 1 <= row["initial_life"] <= 99):
            raise ValueError(f"Invalid strategy: {row['name']}")
        seen.add(row["band_id"])
        values = [json.dumps(row[key], ensure_ascii=False) for key in ("band_id", "name", "initiator")]
        pact = json.dumps(row.get("alliance") or "", ensure_ascii=False)
        effect = json.dumps(row["effect"], ensure_ascii=False)
        flags = [str(term in row["effect"]).lower() for term in ("被动效果", "点击使用", "拖拽使用")]
        lines.append(f"    {{ {', '.join(values)}, {row['initial_life']}, {pact}, {effect}, {', '.join(flags)} }},")
    lines += ["}};", "}", ""]
    args.output.write_text("\n".join(lines), encoding="utf-8")


if __name__ == "__main__":
    main()
